//! Monospace 4-bit-alpha bitmap fonts (generated by `tools/gen_font.py`).

mod data;
pub use data::{BODY, HUGE, SMALL, TITLE};

use bp_hal::{Canvas, Rgb};

pub struct Font {
    pub width: u16,
    pub height: u16,
    pub baseline: u16,
    pub first: u8,
    pub last: u8,
    pub glyph_stride: usize,
    pub data: &'static [u8],
}

impl Font {
    /// Width in pixels of `text` (monospace).
    pub fn text_width(&self, text: &str) -> i32 {
        text.chars().count() as i32 * self.width as i32
    }

    /// Draw one glyph with its top-left at (x, y). Unknown chars render as '?'.
    pub fn draw_char(&self, c: &mut dyn Canvas, x: i32, y: i32, ch: char, color: Rgb) {
        let code = ch as u32;
        let idx = if code >= self.first as u32 && code <= self.last as u32 {
            (code - self.first as u32) as usize
        } else {
            (b'?' - self.first) as usize
        };
        let base = idx * self.glyph_stride;
        let (w, h) = (self.width as usize, self.height as usize);
        for py in 0..h {
            for px in 0..w {
                let n = py * w + px;
                let byte = self.data[base + n / 2];
                let nib = if n % 2 == 0 { byte >> 4 } else { byte & 0x0F };
                if nib != 0 {
                    c.blend_pixel(x + px as i32, y + py as i32, color, nib * 17);
                }
            }
        }
    }

    /// Draw a string with its top-left at (x, y). Returns the x after the text.
    pub fn draw(&self, c: &mut dyn Canvas, x: i32, y: i32, text: &str, color: Rgb) -> i32 {
        let mut cx = x;
        for ch in text.chars() {
            self.draw_char(c, cx, y, ch, color);
            cx += self.width as i32;
        }
        cx
    }

    /// Draw text horizontally centred in [x, x+w).
    pub fn draw_centered(&self, c: &mut dyn Canvas, x: i32, w: i32, y: i32, text: &str, color: Rgb) {
        let tw = self.text_width(text);
        self.draw(c, x + (w - tw) / 2, y, text, color);
    }
}
